var features = (msg.payload && msg.payload.features) || [];
node.status({ fill: 'blue', shape: 'dot', text: features.length + ' quakes in past hour (worldwide)' });

var msgs = features.map(function (f) {
    return { quake: f };
});
return [msgs];

// ---- config -----------------------------------------------------------
// Same wider TN + overlap box used for the Lightning flow (a little north
// of Bowling Green KY, south of Decatur AL, west past Jonesboro AR, east
// past Asheville NC).
var TN_BBOX = { latMin: 34.3, latMax: 37.2, lonMin: -91.2, lonMax: -82.0 }; // var TN_BBOX = { latMin: 24.5, latMax: 49.5, lonMin: -125.0, lonMax: -66.5 };

// NOT verified against a real ATAK-dropped marker -- same caveat as the
// Lightning/NWS flows. Adjust once you've tested what actually renders
// well (see the yellow-clover vs. spot-marker lesson from Lightning).
var cotType = "b-m-p-s-m";
var channelName = "NWS"; // set to your actual channel name
var staleHours = 1; // earthquakes stay operationally relevant longer than a lightning strike
// -------------------------------------------------------------------------

function esc(s) {
    return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;")
        .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

var f = msg.quake;
if (!f || !f.geometry || !f.geometry.coordinates) { return null; }
var p = f.properties || {};

var lon = f.geometry.coordinates[0];
var lat = f.geometry.coordinates[1];
var depthKm = f.geometry.coordinates[2];

if (lat === undefined || lon === undefined) { return null; }
if (lat < TN_BBOX.latMin || lat > TN_BBOX.latMax ||
    lon < TN_BBOX.lonMin || lon > TN_BBOX.lonMax) {
    return null;
}

var now = new Date();
var eventTime = p.time ? new Date(p.time) : now;
var stale = new Date(now.getTime() + staleHours * 60 * 60 * 1000).toISOString();

var uid = "usgs-eq-" + (f.id || (p.time + "-" + lat.toFixed(3) + "-" + lon.toFixed(3)));

var remarksParts = [];
remarksParts.push(p.title || ("M" + p.mag + " earthquake"));
remarksParts.push("Magnitude: " + p.mag + " (" + (p.magType || "?") + ")");
remarksParts.push("Depth: " + depthKm + " km");
if (p.place) { remarksParts.push("Location: " + p.place); }
if (p.tsunami) { remarksParts.push("TSUNAMI WARNING FLAG SET"); }
if (p.alert) { remarksParts.push("PAGER alert: " + p.alert); }
if (p.url) { remarksParts.push("Details: " + p.url); }

var cot = '<?xml version="1.0" encoding="UTF-8"?>' +
    '<event version="2.0" uid="' + esc(uid) + '" type="' + cotType + '" how="m-g" ' +
    'time="' + eventTime.toISOString() + '" start="' + eventTime.toISOString() + '" stale="' + stale + '">' +
    '<point lat="' + lat.toFixed(6) + '" lon="' + lon.toFixed(6) + '" hae="' + (-1 * (depthKm || 0) * 1000).toFixed(0) + '" ce="9999999.0" le="9999999.0"/>' +
    '<detail>' +
    '<contact callsign="' + esc(p.title || "Earthquake") + '"/>' +
    '<color value="-32768"/>' +
    '<remarks>' + esc(remarksParts.join(" | ")) + '</remarks>' +
    '<marti><dest name="' + esc(channelName) + '"/></marti>' +
    '</detail>' +
    '</event>';

msg.payload = cot;
return msg;
